let mimeType = "";
let newBinary = undefined;
if (keys.length > 0) {
  hasFile = true;
  const b = binary[keys[0]];
  fileName = (b && b.fileName) ? b.fileName : "uploaded";
  mimeType = (b && b.mimeType) ? b.mimeType : "";
  let ext = (b && b.fileExtension) ? String(b.fileExtension) : "";
  if (!ext && fileName.indexOf(".") >= 0) { ext = fileName.split(".").pop(); }
  ext = String(ext || "").toLowerCase().replace(".", "");
  if (!ext) {
    if (mimeType.indexOf("csv") >= 0) ext = "csv";
    else if (mimeType.indexOf("sheet") >= 0 || mimeType.indexOf("openxml") >= 0) ext = "xlsx";
    else if (mimeType.indexOf("ms-excel") >= 0) ext = "xls";
  }
  fileExt = ext;
  newBinary = { data: b };
}
const out = {
  json: {
    hasFile: hasFile,
    fileName: fileName,
    fileExt: fileExt,
    mimeType: mimeType,
    chatInput: j.chatInput || "",
    sessionId: j.sessionId || "default",
  },
};
if (newBinary) out.binary = newBinary;
return out;

const items = $input.all();
const rows = items.map(function (i) { return i.json; }).filter(function (r) { return r && Object.keys(r).length > 0; });
const sessionId = $("Inspect Input").first().json.sessionId || "default";
const fileName = $("Inspect Input").first().json.fileName || "uploaded";

if (rows.length === 0) {
  return [{ json: { error: true, message: "The uploaded file is empty or could not be parsed into rows.", sessionId: sessionId, fileName: fileName } }];
}

const columns = Object.keys(rows[0]);

function isEmpty(v) { return v === null || v === undefined || String(v).trim() === ""; }
function toNum(v) {
  if (isEmpty(v)) return NaN;
  const s = String(v).replace(/[$,%\s]/g, "").replace(/,/g, "");
  const n = Number(s);
  return isFinite(n) ? n : NaN;
}
function looksBool(v) { const s = String(v).trim().toLowerCase(); return s === "true" || s === "false" || s === "yes" || s === "no"; }
function looksDate(v) {
  const s = String(v).trim();
  if (!/[0-9]/.test(s)) return false;
  if (!/[-\/:]/.test(s) && !/\d{4}/.test(s)) return false;
  const t = Date.parse(s);
  return !isNaN(t);
}

const profileCols = [];
for (let c = 0; c < columns.length; c++) {
  const col = columns[c];
  let missing = 0, numericCount = 0, boolCount = 0, dateCount = 0, nonEmpty = 0;
  const distinct = {};
  const nums = [];
  for (let r = 0; r < rows.length; r++) {
    const v = rows[r][col];
    if (isEmpty(v)) { missing++; continue; }
    nonEmpty++;
    distinct[String(v)] = true;
    const n = toNum(v);
    if (!isNaN(n)) { numericCount++; nums.push(n); }
    if (looksBool(v)) boolCount++;
    if (looksDate(v)) dateCount++;
  }
  let type = "text";
  if (nonEmpty > 0 && numericCount === nonEmpty) type = "numeric";
  else if (nonEmpty > 0 && boolCount === nonEmpty) type = "boolean";
  else if (nonEmpty > 0 && dateCount === nonEmpty) type = "date";
  const info = { name: col, type: type, missing: missing, distinct: Object.keys(distinct).length };
  if (type === "numeric" && nums.length > 0) {
    const sorted = nums.slice().sort(function (a, b) { return a - b; });
    const sum = nums.reduce(function (a, b) { return a + b; }, 0);
    const mid = Math.floor(sorted.length / 2);
    const median = sorted.length % 2 ? sorted[mid] : (sorted[mid - 1] + sorted[mid]) / 2;
    info.stats = { min: sorted[0], max: sorted[sorted.length - 1], mean: sum / nums.length, median: median, sum: sum };
  }
  profileCols.push(info);
}

const sample = rows.slice(0, 5);
const profile = {
  fileName: fileName,
  rowCount: rows.length,
  colCount: columns.length,
  columns: profileCols,
  sample: sample,
};

return [{ json: {
  error: false,
  sessionId: sessionId,
  fileName: fileName,
  rowCount: rows.length,
  colCount: columns.length,
  profile_json: JSON.stringify(profile),
  dataset_json: JSON.stringify(rows),
