const p = $("Build Profile").first().json;
if (p.error) { return [{ json: { output: "\u26A0\uFE0F " + p.message } }]; }
const prof = JSON.parse(p.profile_json);
const cols = prof.columns.map(function (c) { return "- **" + c.name + "** (" + c.type + ")"; }).join("\n");
let msg = "";
msg += "\u2705 **" + prof.fileName + "** loaded successfully.\n\n";
msg += "- Rows: **" + prof.rowCount + "**\n";
msg += "- Columns: **" + prof.colCount + "**\n\n";
msg += "**Detected columns:**\n" + cols + "\n\n";
msg += "You can now ask questions such as \"What is the total sales?\", \"Show the top 5 products by sales\", \"Sales by region and category\", \"How did sales change year over year?\", or \"Give me a summary of this dataset\".";
return [{ json: { output: msg } }];

const ext = $("Inspect Input").first().json.fileExt || "unknown";
const msg = "\u26A0\uFE0F Unsupported file type (" + ext + "). Please upload a CSV (.csv) or Excel (.xlsx / .xls) file.";
return [{ json: { output: msg } }];

const spec = ($("Interpret Question").first().json.output) || $input.first().json.output || {};
const sess = $("Get Session").first().json;
let rows = [];
try { rows = JSON.parse(sess.dataset_json || "[]"); } catch (e) { rows = []; }
let profile = { columns: [] };
try { profile = JSON.parse(sess.profile_json || "{}"); } catch (e) {}
const question = $("Chat").first().json.chatInput || "";

function isEmpty(v) { return v === null || v === undefined || String(v).trim() === ""; }
function toNum(v) { if (isEmpty(v)) return NaN; const s = String(v).replace(/[$,%\s]/g, "").replace(/,/g, ""); const n = Number(s); return isFinite(n) ? n : NaN; }
function fmt(n) { if (typeof n !== "number" || !isFinite(n)) return String(n); const r = Math.round(n * 100) / 100; return r.toLocaleString("en-US"); }
const colNames = rows.length ? Object.keys(rows[0]) : (profile.columns || []).map(function (c) { return c.name; });
function resolve(name) {
  if (!name) return null;
  const lc = String(name).toLowerCase().trim();
  for (let i = 0; i < colNames.length; i++) { if (colNames[i].toLowerCase() === lc) return colNames[i]; }
  for (let i = 0; i < colNames.length; i++) { if (colNames[i].toLowerCase().indexOf(lc) >= 0 || lc.indexOf(colNames[i].toLowerCase()) >= 0) return colNames[i]; }
  return null;
}
function numericCols() { return (profile.columns || []).filter(function (c) { return c.type === "numeric"; }).map(function (c) { return c.name; }); }
function categoryCols() { return (profile.columns || []).filter(function (c) { return c.type === "text" || c.type === "boolean"; }).map(function (c) { return c.name; }); }
function dateColsList() { return (profile.columns || []).filter(function (c) { return c.type === "date"; }).map(function (c) { return c.name; }); }

function parseDate(v) {
  if (isEmpty(v)) return null;
  const s = String(v).trim();
  if (/^\d{4}[-\/]\d{1,2}[-\/]\d{1,2}/.test(s)) { const t = Date.parse(s); return isNaN(t) ? null : new Date(t); }
  const m = s.match(/^(\d{1,2})[-\/](\d{1,2})[-\/](\d{4})/);
  if (m) { let a = parseInt(m[1], 10), b = parseInt(m[2], 10), y = parseInt(m[3], 10); let day, mon; if (a > 12) { day = a; mon = b; } else if (b > 12) { mon = a; day = b; } else { day = a; mon = b; } const d = new Date(y, mon - 1, day); return isNaN(d.getTime()) ? null : d; }
  const t = Date.parse(s); return isNaN(t) ? null : new Date(t);
}
function periodKey(d, period) {
  if (!d) return "(blank)";
  const y = d.getFullYear(); const mo = d.getMonth() + 1;
  if (period === "year") return String(y);
  if (period === "quarter") return y + "-Q" + (Math.floor((mo - 1) / 3) + 1);
  if (period === "month") return y + "-" + (mo < 10 ? "0" + mo : mo);
  if (period === "day") return y + "-" + (mo < 10 ? "0" + mo : mo) + "-" + ((d.getDate() < 10 ? "0" : "") + d.getDate());
  return String(y);
}

function aggregate(values, operation) {
  const nums = values.map(toNum).filter(function (n) { return !isNaN(n); });
  if (operation === "count") return values.filter(function (v) { return !isEmpty(v); }).length;
  if (operation === "count_distinct") { const d = {}; values.forEach(function (v) { if (!isEmpty(v)) d[String(v)] = true; }); return Object.keys(d).length; }
  if (!nums.length) return null;
  if (operation === "sum") return nums.reduce(function (a, b) { return a + b; }, 0);
  if (operation === "average") return nums.reduce(function (a, b) { return a + b; }, 0) / nums.length;
  if (operation === "min") return Math.min.apply(null, nums);
  if (operation === "max") return Math.max.apply(null, nums);
  if (operation === "median") { const s = nums.slice().sort(function (a, b) { return a - b; }); const m = Math.floor(s.length / 2); return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2; }
  if (operation === "variance") { const mean = nums.reduce(function (a, b) { return a + b; }, 0) / nums.length; return nums.reduce(function (a, b) { return a + (b - mean) * (b - mean); }, 0) / nums.length; }
  if (operation === "stddev") { const mean = nums.reduce(function (a, b) { return a + b; }, 0) / nums.length; return Math.sqrt(nums.reduce(function (a, b) { return a + (b - mean) * (b - mean); }, 0) / nums.length); }
  return null;
}
function percentile(nums, p) { if (!nums.length) return null; const s = nums.slice().sort(function (a, b) { return a - b; }); const idx = (p / 100) * (s.length - 1); const lo = Math.floor(idx), hi = Math.ceil(idx); if (lo === hi) return s[lo]; return s[lo] + (s[hi] - s[lo]) * (idx - lo); }
function pearson(xs, ys) { const n = Math.min(xs.length, ys.length); const px = [], py = []; for (let i = 0; i < n; i++) { const a = toNum(xs[i]), b = toNum(ys[i]); if (!isNaN(a) && !isNaN(b)) { px.push(a); py.push(b); } } if (px.length < 2) return null; const mx = px.reduce(function (a, b) { return a + b; }, 0) / px.length; const my = py.reduce(function (a, b) { return a + b; }, 0) / py.length; let num = 0, dx = 0, dy = 0; for (let i = 0; i < px.length; i++) { const a = px[i] - mx, b = py[i] - my; num += a * b; dx += a * a; dy += b * b; } if (dx === 0 || dy === 0) return null; return num / Math.sqrt(dx * dy); }
function modeOf(nums) { const c = {}; let best = null, bestCount = 0; for (let i = 0; i < nums.length; i++) { const k = nums[i]; c[k] = (c[k] || 0) + 1; if (c[k] > bestCount) { bestCount = c[k]; best = k; } } return bestCount > 1 ? best : null; }
function skewness(nums) { const n = nums.length; if (n < 3) return null; const mean = nums.reduce(function (a, b) { return a + b; }, 0) / n; const sd = Math.sqrt(nums.reduce(function (a, b) { return a + (b - mean) * (b - mean); }, 0) / n); if (sd === 0) return null; return nums.reduce(function (a, b) { return a + Math.pow((b - mean) / sd, 3); }, 0) / n; }
function pickIdCols(metric) { const out = []; const dates = dateColsList(); const cats = categoryCols(); for (let i = 0; i < dates.length && out.length < 2; i++) { if (dates[i] !== metric) out.push(dates[i]); } for (let i = 0; i < cats.length && out.length < 5; i++) { if (cats[i] !== metric && out.indexOf(cats[i]) < 0) out.push(cats[i]); } return out; }
function pickRowFacts(r, cols) { const o = {}; cols.forEach(function (c) { o[c] = r[c]; }); return o; }

function applyFilters(data, filters) {
  if (!filters || !filters.length) return data;
  return data.filter(function (row) {
    for (let f = 0; f < filters.length; f++) {
      const col = resolve(filters[f].column); if (!col) continue;
      const raw = row[col]; const op = filters[f].op; const val = filters[f].value;
      if (op === "year") { const d = parseDate(raw); if (!d || String(d.getFullYear()) !== String(val)) return false; continue; }
      if (op === "contains") { if (String(raw).toLowerCase().indexOf(String(val).toLowerCase()) < 0) return false; continue; }
      const rn = toNum(raw); const vn = toNum(val); const bothNum = !isNaN(rn) && !isNaN(vn);
      if (op === "eq") { if (bothNum ? rn !== vn : String(raw).toLowerCase() !== String(val).toLowerCase()) return false; }
      else if (op === "neq") { if (bothNum ? rn === vn : String(raw).toLowerCase() === String(val).toLowerCase()) return false; }
      else if (op === "gt") { if (!(rn > vn)) return false; }
      else if (op === "gte") { if (!(rn >= vn)) return false; }
      else if (op === "lt") { if (!(rn < vn)) return false; }
      else if (op === "lte") { if (!(rn <= vn)) return false; }
    }
    return true;
  });
}

function stepResult(label, answer, table_md, facts) { return { label: label || "", answer: answer || "", table_md: table_md || "", facts: facts || {} }; }

function runStep(step) {
  const label = step.label || step.op || "step";
  const data = applyFilters(rows, step.filters);
  const op = step.op;

  if (op === "aggregate") {
    const metric = resolve(step.column);
    if (!metric) return stepResult(label, "Could not find a column matching \"" + step.column + "\". Numeric columns: " + numericCols().join(", ") + ".", "", { error: "missing_column" });
    const operation = (step.operation && step.operation !== "none") ? step.operation : "sum";
    const val = aggregate(data.map(function (r) { return r[metric]; }), operation);
    if (val === null) return stepResult(label, "Could not compute " + operation + " on " + metric + ".", "", { error: "no_values" });
    const lbl = { sum: "Total", average: "Average", count: "Count of", count_distinct: "Distinct count of", min: "Minimum", max: "Maximum", median: "Median" }[operation] || operation;
    return stepResult(label, "**" + lbl + " " + metric + ":** " + fmt(val), "", { operation: operation, column: metric, value: val, rowsConsidered: data.length });
  }

  if (op === "groupby" || op === "topn") {
    if (step.derived_formula && step.derived_formula !== "none" && resolve(step.column_b)) { return runStep(Object.assign({}, step, { op: "derived" })); }
    const cats = (step.group_by || []).map(resolve).filter(function (c) { return c; });
    const metric = resolve(step.column);
    if (!cats.length) return stepResult(label, "Could not find a category column to group by.", "", { error: "missing_group" });
    if (!metric) return stepResult(label, "Could not find a numeric column matching \"" + step.column + "\".", "", { error: "missing_column" });
    const operation = (step.operation && step.operation !== "none") ? step.operation : "sum";
    const groups = {};
    data.forEach(function (r) { const k = cats.map(function (c) { return isEmpty(r[c]) ? "(blank)" : String(r[c]); }).join(" | "); if (!groups[k]) groups[k] = []; groups[k].push(r[metric]); });
    let arr = Object.keys(groups).map(function (k) { return { k: k, v: aggregate(groups[k], operation) }; }).filter(function (x) { return x.v !== null; });
    const dir = step.sort_direction === "asc" ? 1 : -1;
    arr.sort(function (a, b) { return (a.v - b.v) * dir; });
    const limit = (op === "topn" && step.top_n && step.top_n > 0) ? step.top_n : arr.length;
    const top = arr.slice(0, limit);
    let t = "| " + cats.join(" / ") + " | " + operation + " of " + metric + " |\n| --- | ---: |\n";
    top.forEach(function (x) { t += "| " + x.k + " | " + fmt(x.v) + " |\n"; });
    const best = top.length ? top[0] : null;
    const answer = best ? ("**" + best.k + "** has the " + (dir < 0 ? "highest" : "lowest") + " " + operation + " of " + metric + " (" + fmt(best.v) + ").") : "No data to group.";
    return stepResult(label, answer, t, { groups: top.slice(0, 20) });
  }

  if (op === "derived") {
    const a = resolve(step.column); const b = resolve(step.column_b);
    if (!a || !b) return stepResult(label, "A derived metric needs two valid columns. Numeric columns: " + numericCols().join(", ") + ".", "", { error: "missing_column" });
    const operation = (step.operation && step.operation !== "none") ? step.operation : "sum";
    const formula = step.derived_formula || "ratio";
    let sym = "";
    if (formula === "ratio") sym = a + " / " + b;
    else if (formula === "percent") sym = a + " / " + b + " * 100";
    else if (formula === "difference") sym = a + " - " + b;
    else if (formula === "product") sym = a + " * " + b;
    function combine(av, bv) {
      if (av === null || bv === null) return null;
      if (formula === "ratio") return bv === 0 ? null : av / bv;
      if (formula === "percent") return bv === 0 ? null : (av / bv) * 100;
      if (formula === "difference") return av - bv;
      if (formula === "product") return av * bv;
      return null;
    }
    const cats = (step.group_by || []).map(resolve).filter(function (c) { return c; });
    if (cats.length) {
      const groups = {};
      data.forEach(function (r) { const k = cats.map(function (c) { return isEmpty(r[c]) ? "(blank)" : String(r[c]); }).join(" | "); if (!groups[k]) groups[k] = { a: [], b: [] }; groups[k].a.push(r[a]); groups[k].b.push(r[b]); });
      let arr = Object.keys(groups).map(function (k) { const av = aggregate(groups[k].a, operation); const bv = aggregate(groups[k].b, operation); return { k: k, av: av, bv: bv, v: combine(av, bv) }; }).filter(function (x) { return x.v !== null && isFinite(x.v); });
      if (!arr.length) return stepResult(label, "Could not compute " + sym + " for any group.", "", { error: "no_values" });
      const dir = step.sort_direction === "asc" ? 1 : -1;
      arr.sort(function (x, y) { return (x.v - y.v) * dir; });
      const limit = (step.top_n && step.top_n > 0) ? step.top_n : arr.length;
      const top = arr.slice(0, limit);
      const unit = formula === "percent" ? "%" : "";
      let t = "| " + cats.join(" / ") + " | " + operation + " of " + a + " | " + operation + " of " + b + " | " + label + " |\n| --- | ---: | ---: | ---: |\n";
      top.forEach(function (x) { t += "| " + x.k + " | " + fmt(x.av) + " | " + fmt(x.bv) + " | " + fmt(x.v) + unit + " |\n"; });
      const best = top[0];
      const answer = "**" + best.k + "** has the " + (dir < 0 ? "highest" : "lowest") + " " + label + " (" + fmt(best.v) + unit + "), computed as " + sym + " independently per group.";
      return stepResult(label, answer, t, { formula: formula, a: a, b: b, groupBy: cats, groups: top.slice(0, 20).map(function (x) { return { group: x.k, aValue: x.av, bValue: x.bv, value: x.v }; }) });
    }
    const av = aggregate(data.map(function (r) { return r[a]; }), operation);
    const bv = aggregate(data.map(function (r) { return r[b]; }), operation);
    if (av === null || bv === null) return stepResult(label, "Could not compute the derived metric.", "", { error: "no_values" });
    const val = combine(av, bv);
    if (val === null) return stepResult(label, "Could not compute " + sym + " (division by zero or no data).", "", { error: "compute" });
    const disp = formula === "percent" ? (fmt(val) + "%") : fmt(val);
    return stepResult(label, "**" + label + ":** " + disp + " (" + sym + ", " + operation + "s)", "", { formula: formula, a: a, b: b, aValue: av, bValue: bv, value: val });
  }

  if (op === "compare") {
    const metric = resolve(step.column); const dcol = resolve(step.date_column) || dateColsList()[0];
    const period = (step.period && step.period !== "none") ? step.period : "year";
    if (!metric) return stepResult(label, "Could not find a numeric column matching \"" + step.column + "\".", "", { error: "missing_column" });
    if (!dcol) return stepResult(label, "Could not find a date column to compare over time.", "", { error: "missing_date" });
    const operation = (step.operation && step.operation !== "none") ? step.operation : "sum";
    const groups = {};
    data.forEach(function (r) { const k = periodKey(parseDate(r[dcol]), period); if (!groups[k]) groups[k] = []; groups[k].push(r[metric]); });
    const keys = Object.keys(groups).filter(function (k) { return k !== "(blank)"; }).sort();
    let t = "| Period | " + operation + " of " + metric + " | Change | % Change |\n| --- | ---: | ---: | ---: |\n";
    let prev = null; const series = [];
    keys.forEach(function (k) { const v = aggregate(groups[k], operation); let ch = "-", pc = "-"; if (prev !== null && v !== null) { const d = v - prev; ch = (d >= 0 ? "+" : "") + fmt(d); pc = prev === 0 ? "-" : ((d / prev * 100 >= 0 ? "+" : "") + fmt(d / prev * 100) + "%"); } t += "| " + k + " | " + fmt(v) + " | " + ch + " | " + pc + " |\n"; series.push({ period: k, value: v }); prev = v; });
    let answer = "Trend of " + operation + " " + metric + " by " + period + ".";
    if (series.length >= 2) { const first = series[0], last = series[series.length - 1]; if (first.value) { const g = (last.value - first.value) / first.value * 100; answer = metric + " went from " + fmt(first.value) + " (" + first.period + ") to " + fmt(last.value) + " (" + last.period + "), a " + (g >= 0 ? "+" : "") + fmt(g) + "% change overall."; } }
    return stepResult(label, answer, t, { series: series });
  }

  if (op === "stats") {
    const metric = resolve(step.column);
    if (!metric) return stepResult(label, "Could not find a numeric column matching \"" + step.column + "\".", "", { error: "missing_column" });
    const nums = data.map(function (r) { return r[metric]; }).map(toNum).filter(function (n) { return !isNaN(n); });
    if (!nums.length) return stepResult(label, "No numeric values found in " + metric + ".", "", { error: "no_values" });
    const mean = nums.reduce(function (a, b) { return a + b; }, 0) / nums.length;
    const variance = nums.reduce(function (a, b) { return a + (b - mean) * (b - mean); }, 0) / nums.length;
    const sd = Math.sqrt(variance);
