    const med = sorted.length % 2 ? sorted[Math.floor(sorted.length / 2)] : (sorted[sorted.length / 2 - 1] + sorted[sorted.length / 2]) / 2;
    const q1 = percentile(nums, 25), q3 = percentile(nums, 75); const iqr = q3 - q1;
    const mode = modeOf(nums); const skew = skewness(nums);
    let t = "| Statistic | Value |\n| --- | ---: |\n";
    t += "| Count | " + fmt(nums.length) + " |\n| Min | " + fmt(sorted[0]) + " |\n| Max | " + fmt(sorted[sorted.length - 1]) + " |\n| Range | " + fmt(sorted[sorted.length - 1] - sorted[0]) + " |\n| Mean | " + fmt(mean) + " |\n| Median | " + fmt(med) + " |\n";
    if (mode !== null) t += "| Mode | " + fmt(mode) + " |\n";
    t += "| Std Dev | " + fmt(sd) + " |\n| Variance | " + fmt(variance) + " |\n| Q1 (P25) | " + fmt(q1) + " |\n| Q3 (P75) | " + fmt(q3) + " |\n| IQR | " + fmt(iqr) + " |\n";
    if (skew !== null) t += "| Skewness | " + fmt(skew) + " |\n";
    const ps = (step.percentiles && step.percentiles.length) ? step.percentiles : [];
    ps.forEach(function (p) { t += "| P" + p + " | " + fmt(percentile(nums, p)) + " |\n"; });
    return stepResult(label, "Distribution statistics for **" + metric + "** (mean " + fmt(mean) + ", median " + fmt(med) + ", std dev " + fmt(sd) + ").", t, { mean: mean, median: med, mode: mode, stddev: sd, variance: variance, min: sorted[0], max: sorted[sorted.length - 1], range: sorted[sorted.length - 1] - sorted[0], q1: q1, q3: q3, iqr: iqr, skewness: skew });
  }

  if (op === "outliers") {
    const metric = resolve(step.column);
    if (!metric) return stepResult(label, "Could not find a numeric column matching \"" + step.column + "\".", "", { error: "missing_column" });
    const pairs = data.map(function (r) { return { r: r, v: toNum(r[metric]) }; }).filter(function (x) { return !isNaN(x.v); });
    if (!pairs.length) return stepResult(label, "No numeric values found in " + metric + ".", "", { error: "no_values" });
    const nums = pairs.map(function (x) { return x.v; });
    const q1 = percentile(nums, 25), q3 = percentile(nums, 75); const iqr = q3 - q1;
    const lo = q1 - 1.5 * iqr, hi = q3 + 1.5 * iqr;
    const idCols = pickIdCols(metric);
    const outs = pairs.filter(function (x) { return x.v < lo || x.v > hi; }).sort(function (a, b) { return b.v - a.v; });
    const shown = outs.slice(0, 15);
    let t = "| " + (idCols.join(" | ") ? idCols.join(" | ") + " | " : "") + metric + " | Flag |\n| " + idCols.map(function () { return "---"; }).join(" | ") + (idCols.length ? " | " : "") + "---: | --- |\n";
    shown.forEach(function (x) { const cells = idCols.map(function (c) { return String(x.r[c]); }); t += "| " + (cells.length ? cells.join(" | ") + " | " : "") + fmt(x.v) + " | " + (x.v > hi ? "high" : "low") + " |\n"; });
    const answer = "Found **" + outs.length + "** potential outlier(s) in " + metric + " using the IQR method (bounds: below " + fmt(lo) + " or above " + fmt(hi) + "; Q1=" + fmt(q1) + ", Q3=" + fmt(q3) + ", IQR=" + fmt(iqr) + ")." + (outs.length > shown.length ? " Showing the top " + shown.length + "." : "");
    return stepResult(label, answer, outs.length ? t : "", { method: "IQR (1.5x)", q1: q1, q3: q3, iqr: iqr, lowerBound: lo, upperBound: hi, outlierCount: outs.length });
  }

  if (op === "extreme") {
    const metric = resolve(step.column);
    if (!metric) return stepResult(label, "Could not find a numeric column matching \"" + step.column + "\".", "", { error: "missing_column" });
    const pairs = data.map(function (r) { return { r: r, v: toNum(r[metric]) }; }).filter(function (x) { return !isNaN(x.v); });
    if (!pairs.length) return stepResult(label, "No numeric values found in " + metric + ".", "", { error: "no_values" });
    const wantMin = step.sort_direction === "asc" || step.operation === "min";
    pairs.sort(function (a, b) { return wantMin ? (a.v - b.v) : (b.v - a.v); });
    const n = (step.top_n && step.top_n > 0) ? step.top_n : 1;
    const picks = pairs.slice(0, n);
    const idCols = pickIdCols(metric);
    let t = "| " + (idCols.join(" | ") ? idCols.join(" | ") + " | " : "") + metric + " |\n| " + idCols.map(function () { return "---"; }).join(" | ") + (idCols.length ? " | " : "") + "---: |\n";
    picks.forEach(function (x) { const cells = idCols.map(function (c) { return String(x.r[c]); }); t += "| " + (cells.length ? cells.join(" | ") + " | " : "") + fmt(x.v) + " |\n"; });
    const top = picks[0];
    const answer = "The record with the " + (wantMin ? "lowest" : "highest") + " " + metric + " is **" + fmt(top.v) + "**" + (idCols.length ? " (" + idCols.map(function (c) { return c + ": " + top.r[c]; }).join(", ") + ")" : "") + ".";
    return stepResult(label, answer, t, { direction: wantMin ? "min" : "max", value: top.v, row: pickRowFacts(top.r, idCols) });
  }

  if (op === "distribution") {
    const metric = resolve(step.column);
    if (!metric) return stepResult(label, "Could not find a column matching \"" + step.column + "\".", "", { error: "missing_column" });
    const colInfo = (profile.columns || []).filter(function (c) { return c.name === metric; })[0];
    const isNumeric = colInfo && colInfo.type === "numeric";
    if (isNumeric) {
      const nums = data.map(function (r) { return r[metric]; }).map(toNum).filter(function (n) { return !isNaN(n); });
      if (!nums.length) return stepResult(label, "No numeric values found in " + metric + ".", "", { error: "no_values" });
      const mn = Math.min.apply(null, nums), mx = Math.max.apply(null, nums);
      const bins = 8; const width = (mx - mn) / bins || 1; const counts = [];
      for (let i = 0; i < bins; i++) counts.push(0);
      nums.forEach(function (n) { let idx = Math.floor((n - mn) / width); if (idx >= bins) idx = bins - 1; if (idx < 0) idx = 0; counts[idx]++; });
      let t = "| Range | Count |\n| --- | ---: |\n";
      for (let i = 0; i < bins; i++) { const lo = mn + i * width, hi = mn + (i + 1) * width; const lb = (i === bins - 1) ? ("[" + fmt(lo) + " - " + fmt(hi) + "]") : ("[" + fmt(lo) + " - " + fmt(hi) + ")"); t += "| " + lb + " | " + fmt(counts[i]) + " |\n"; }
      return stepResult(label, "Histogram of **" + metric + "** across " + bins + " contiguous, non-overlapping bins from " + fmt(mn) + " to " + fmt(mx) + " (each value counted once; bins are [low, high), final bin inclusive).", t, { min: mn, max: mx, binWidth: width, counts: counts });
    }
    const groups = {};
    data.forEach(function (r) { const k = isEmpty(r[metric]) ? "(blank)" : String(r[metric]); groups[k] = (groups[k] || 0) + 1; });
    let arr = Object.keys(groups).map(function (k) { return { k: k, v: groups[k] }; }).sort(function (a, b) { return b.v - a.v; }).slice(0, 20);
    let t = "| " + metric + " | Count |\n| --- | ---: |\n";
    arr.forEach(function (x) { t += "| " + x.k + " | " + fmt(x.v) + " |\n"; });
    return stepResult(label, "Value counts for **" + metric + "** (top " + arr.length + ").", t, { counts: arr });
  }

  if (op === "correlation") {
    const a = resolve(step.column); const b = resolve(step.column_b);
    if (!a || !b) return stepResult(label, "Correlation needs two numeric columns. Numeric columns: " + numericCols().join(", ") + ".", "", { error: "missing_column" });
    const r = pearson(data.map(function (x) { return x[a]; }), data.map(function (x) { return x[b]; }));
    if (r === null) return stepResult(label, "Could not compute correlation between " + a + " and " + b + ".", "", { error: "compute" });
    let strength = Math.abs(r) < 0.2 ? "very weak" : Math.abs(r) < 0.4 ? "weak" : Math.abs(r) < 0.6 ? "moderate" : Math.abs(r) < 0.8 ? "strong" : "very strong";
    const dirn = r >= 0 ? "positive" : "negative";
    return stepResult(label, "Correlation between **" + a + "** and **" + b + "** is **" + fmt(r) + "** (" + strength + " " + dirn + ").", "", { r: r, a: a, b: b });
  }

  return stepResult(label, "Unknown operation: " + op, "", { error: "unknown_op" });
}

function richSummary() {
  const nCols = numericCols(); const cats = categoryCols();
  let md = "### Dataset Overview\n\n| Metric | Value |\n| --- | ---: |\n";
  md += "| Rows | " + fmt(rows.length) + " |\n| Columns | " + fmt(colNames.length) + " |\n";
  md += "| Numeric columns | " + (nCols.join(", ") || "none") + " |\n| Category columns | " + (cats.slice(0, 8).join(", ") || "none") + " |\n";
  let md2 = "";
  if (nCols.length) {
    md2 += "\n### Numeric Columns\n\n| Column | Sum | Mean | Median | Std Dev | Min | Max |\n| --- | ---: | ---: | ---: | ---: | ---: | ---: |\n";
    nCols.forEach(function (c) {
      const vals = rows.map(function (r) { return r[c]; });
      md2 += "| " + c + " | " + fmt(aggregate(vals, "sum")) + " | " + fmt(aggregate(vals, "average")) + " | " + fmt(aggregate(vals, "median")) + " | " + fmt(aggregate(vals, "stddev")) + " | " + fmt(aggregate(vals, "min")) + " | " + fmt(aggregate(vals, "max")) + " |\n";
    });
  }
  let md3 = "";
  if (cats.length && nCols.length) {
    const cat = cats[0]; const metric = nCols[0]; const groups = {};
    rows.forEach(function (r) { const k = isEmpty(r[cat]) ? "(blank)" : String(r[cat]); const n = toNum(r[metric]); if (!isNaN(n)) groups[k] = (groups[k] || 0) + n; });
    const arr = Object.keys(groups).map(function (k) { return { k: k, v: groups[k] }; }).sort(function (a, b) { return b.v - a.v; }).slice(0, 5);
    md3 += "\n### Top " + cat + " by " + metric + "\n\n| " + cat + " | " + metric + " |\n| --- | ---: |\n";
    arr.forEach(function (x) { md3 += "| " + x.k + " | " + fmt(x.v) + " |\n"; });
  }
  return md + md2 + md3;
}

function out(status, answer, table_md, facts) { return [{ json: { status: status, question: question, answer: answer || "", table_md: table_md || "", facts: JSON.stringify(facts || {}) } }]; }

if (!sess.dataset_json) { return out("error", "No dataset is loaded for this conversation.", "", {}); }

if (spec.needs_clarification || spec.intent === "clarify") {
  return out("clarify", spec.clarification_question || "Could you clarify which column you would like me to analyze?", "", { numericColumns: numericCols(), categoryColumns: categoryCols() });
}
if (spec.intent === "unsupported") {
  return out("unsupported", "", "", { numericColumns: numericCols(), categoryColumns: categoryCols() });
}
if (spec.intent === "summary") {
  return out("ok", "Here is a summary of the dataset.", richSummary(), { rows: rows.length, columns: colNames.length });
}

const steps = (spec.steps && spec.steps.length) ? spec.steps : [];
if (!steps.length) { return out("ok", "Here is a summary of the dataset.", richSummary(), { rows: rows.length, columns: colNames.length }); }

const results = [];
for (let i = 0; i < steps.length; i++) {
  let step = steps[i];
  if (step.scope_to_previous_top && i > 0) {
    const prevStep = steps[i - 1] || {};
    const pf = (results[i - 1] && results[i - 1].facts) ? results[i - 1].facts : {};
    let cats = [], topKey = null;
    if (pf.groupBy && pf.groupBy.length && pf.groups && pf.groups.length) { cats = pf.groupBy; topKey = pf.groups[0].group; }
    else if (prevStep.group_by && prevStep.group_by.length && pf.groups && pf.groups.length) { cats = prevStep.group_by.map(resolve).filter(function (c) { return c; }); topKey = pf.groups[0].k; }
    if (cats.length && topKey != null) {
      const parts = String(topKey).split(" | ");
      const inj = [];
      cats.forEach(function (c, idx) { if (parts[idx] !== undefined && parts[idx] !== "(blank)") inj.push({ column: c, op: "eq", value: parts[idx] }); });
      if (inj.length) step = Object.assign({}, step, { filters: (step.filters || []).concat(inj) });
    }
  }
  results.push(runStep(step));
}

let answer = "";
let tables = "";
for (let i = 0; i < results.length; i++) {
  const r = results[i];
  answer += (steps.length > 1 ? ((i + 1) + ". ") : "") + r.answer + "\n";
  if (r.table_md) { tables += "\n### " + r.label + "\n\n" + r.table_md; }
}
const factsArr = results.map(function (r) { return { label: r.label, facts: r.facts }; });
return out("ok", answer.trim(), tables.trim(), { steps: factsArr });

